{
  "title": "The Glass Diver's Passage",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara reads the ruined city from a distant hill.",
      "visual_description": "Mara the Cartographer stands on a grassy hill overlooking a broken royal city, its spires cracked and banners faded. She holds a brass compass that trembles in her ink-stained hand.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of hidden doors.",
      "visual_description": "Inside a collapsed pavilion, the Oracle Lamp flickers on a stone table, its single eye of flame darting as it speaks. Dust motes dance in its glow.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Glass Diver arrives through a cracked window.",
      "visual_description": "Glass Diver steps out of a shattered window pane, his clear helmet reflecting the ruined skyline. His coat glitters with fragments of light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox scouts ahead through rubble.",
      "visual_description": "Tin Fox darts between fallen stones, its key-wind tail spinning. Blue glass eyes scan for movement as it sniffs the air.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Mara marks the castle gates on her map.",
      "visual_description": "Mara kneels behind a collapsed wall, sketching the castle gates with a charcoal stick. The gates are immense, rusted, and partly ajar.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 6,
      "caption": "Oracle Lamp warns of a cursed tower.",
      "visual_description": "The Oracle Lamp's flame turns blue as it gazes at a twisted tower leaning over the city. Shadows writhe on its walls.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "Glass Diver swims through a mirror in the gatehouse.",
      "visual_description": "Glass Diver presses his hand against a dusty mirror, then steps through its surface into a dim chamber on the other side.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Tin Fox finds old royal banners in a courtyard.",
      "visual_description": "Tin Fox noses through a heap of tattered banners embroidered with faded crests, its metal joints clicking in the silence.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Sleeping Tax Collector dozes on a ledger.",
      "visual_description": "In a roofless treasury, the Sleeping Tax Collector snores with his head on a ledger book, stamped papers stuck to his sleeves like armor.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "Mara navigates a maze of frightened townspeople.",
      "visual_description": "Mara weaves through narrow alleys where townspeople huddle in doorways, clutching bundles. She consults her compass, eyes fixed ahead.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver passes through a magic door.",
      "visual_description": "Glass Diver faces a door that ripples like water. He steps into it, his form distorting before reappearing in a hall of mirrors.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Oracle Lamp reveals an armored patrol route.",
      "visual_description": "The Oracle Lamp's flame casts a map of moving dots on the wall. 'They circle the bell tower,' it whispers.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox retrieves a key from a dust pile.",
      "visual_description": "Tin Fox digs with its forepaws in a pile of ash and bone, pulling out a brass key that glints in the dim light.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Sleeping Tax Collector stamps a permit in his sleep.",
      "visual_description": "The Sleeping Tax Collector mumbles and stamps a blank paper with an ink pad, then rolls over without waking.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "Mara leads the group past a patrol of armored figures.",
      "visual_description": "Mara crouches behind a broken cart, guiding Glass Diver and Tin Fox while armored figures march past in the fog.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "Glass Diver opens a sealed vault with the brass key.",
      "visual_description": "Glass Diver inserts the key into a lock on a stone vault. The door swings open to reveal a dark passage.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 17,
      "caption": "The group races across a crumbling bridge.",
      "visual_description": "Mara, Glass Diver, and Tin Fox sprint across a stone bridge that crumbles behind them. The Oracle Lamp swings from Mara's belt, casting long shadows.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Sleeping Tax Collector is left behind, still dreaming.",
      "visual_description": "The bridge collapses, leaving the Sleeping Tax Collector on the far side, still dozing on his ledger as dust settles around him.",
      "characters": ["sleeping_tax_collector"]
    }
  ]
}

